-- =============================================================================
-- Object:      dbo.usp_PushSubscription_SaveForPickupOrder
-- Type:        stored procedure
-- Purpose:     Saves the push subscription of a customer's browser for a pickup order (HU_09). The subscription belongs
--              to the customer of that order, so later orders from the same phone are notified too. Only MobileApp
--              orders qualify; any other id saves nothing.
-- Parameters:  @Id uniqueidentifier - id for a new row (sequential, generated by the API)
--              @ClientOrderId uniqueidentifier - the receipt the customer's phone kept
--              @Endpoint nvarchar(450), @P256dh nvarchar(200), @Auth nvarchar(200) - the browser's subscription
--              @Now datetime2 - current time (UTC)
-- Returns:     Saved bit - 0 when there is no pickup order with that id
-- Author:      JulianH2
-- Jira:        ITACR-15
-- =============================================================================
CREATE OR ALTER PROCEDURE dbo.usp_PushSubscription_SaveForPickupOrder
    @Id uniqueidentifier,
    @ClientOrderId uniqueidentifier,
    @Endpoint nvarchar(450),
    @P256dh nvarchar(200),
    @Auth nvarchar(200),
    @Now datetime2
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @CustomerId uniqueidentifier =
        (SELECT CustomerId FROM dbo.Orders WHERE ClientOrderId = @ClientOrderId AND Channel = N'MobileApp');

    IF @CustomerId IS NULL
    BEGIN
        SELECT CAST(0 AS bit) AS Saved;
        RETURN;
    END;

    BEGIN TRANSACTION;

    UPDATE dbo.PushSubscriptions WITH (UPDLOCK, HOLDLOCK)
    SET CustomerId = @CustomerId, EmployeeId = NULL, P256dh = @P256dh, Auth = @Auth, UpdatedAt = @Now
    WHERE Endpoint = @Endpoint;

    IF @@ROWCOUNT = 0
    BEGIN
        INSERT INTO dbo.PushSubscriptions (Id, EmployeeId, CustomerId, Endpoint, P256dh, Auth, CreatedAt, UpdatedAt)
        VALUES (@Id, NULL, @CustomerId, @Endpoint, @P256dh, @Auth, @Now, @Now);
    END;

    COMMIT TRANSACTION;
    SELECT CAST(1 AS bit) AS Saved;
END;
